import * as THREE from 'three';
import {createPrincipalChairCushion} from './principal-chair-cushion.js';
import {PRINCIPAL_DESK as DESK,PRINCIPAL_SEAT as STAFF,PRINCIPAL_ROCKER as ROCK} from './principal-office-layout.js';
export function buildPrincipalOffice({root,box,sphere,cylinder,mat}){
 const office=new THREE.Group();office.name='principalOffice.landmark';root.add(office);const fixtures=[];
 const group=(name,x=0,z=0,yaw=0)=>{const g=new THREE.Group();g.name='principalOffice.'+name;g.position.set(x,0,z);g.rotation.y=yaw;office.add(g);fixtures.push(g);return g;};
 const soft=(w,h,d,c,x,y,z,p)=>box(w,h,d,c,x,y,z,.06,p);
 const flat=(w,h,d,c,x,y,z,p)=>{const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(c));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;p.add(m);return m;};
 function rolled(w,h,d,color,x,y,z,from,drop,p){const g=new THREE.BoxGeometry(w,h,d,1,1,48),a=g.attributes.position;for(let i=0;i<a.count;i++)a.setY(i,a.getY(i)-drop*THREE.MathUtils.clamp((a.getZ(i)-from)/.07,0,1));a.needsUpdate=true;g.computeVertexNormals();const m=new THREE.Mesh(g,mat(color));m.position.set(x,y,z);m.castShadow=m.receiveShadow=true;m.name='principalOffice.rolled-cushion';p.add(m);return m;}
 const rug=group('lounge-rug',-1.05,1.2);flat(7.1,.012,5.8,'#849e92',0,.023,0,rug);flat(6.88,.008,5.58,'#d6c8a7',0,.032,0,rug);flat(6.56,.005,5.25,'#aabb9f',0,.038,0,rug);
 function sofa(name,width,x,z,yaw,armSides=[-1,1]){const g=group(name,x,z,yaw);soft(width,.39,.62,'#8b7052',0,.30,-.125,g);const count=Math.max(2,Math.round(width/1.55));for(let i=0;i<count;i++)rolled((width-.22)/count-.035,.16,.86,'#e4d6b7',-width/2+.11+(i+.5)*(width-.22)/count,.57,0,.20,.10,g);soft(width,.69,.14,'#b3bc9c',0,1.00,-.51,g);soft(width-.18,.50,.12,'#d8ccab',0,1.05,-.42,g);for(const side of[-1,1]){if(armSides.includes(side))soft(.19,.47,1.00,'#bec5a7',side*(width/2-.085),.78,.015,g);for(const zz of[-.31,.31])flat(.12,.19,.12,'#70563d',side*(width/2-.18),.11,zz,g);}return g;}
 sofa('sofa.back',6.5,-1.05,-.55,0);sofa('sofa.left',3.6,-3.85,1.35,Math.PI/2,[-1]);sofa('sofa.right',3.6,1.75,1.35,-Math.PI/2,[1]);
 const table=group('coffee-table',-1.05,2.05);soft(1.15,.13,.90,'#c19b67',0,.45,0,table);for(const x of[-.40,.40])for(const z of[-.25,.25])flat(.10,.36,.10,'#9a7850',x,.21,z,table);soft(.38,.034,.28,'#eee6ce',-.14,.533,0,table);flat(.29,.012,.22,'#9eac90',-.14,.557,0,table);
 // The principal faces +Z from behind the desk: drawer fronts belong on -Z.
 // Mount handles into that face; plain pedestal backs and the modesty panel face visitors.
 const desk=group('executive-desk',DESK.x,DESK.z);soft(DESK.width,.18,DESK.depth,'#9b714c',0,DESK.top-.09,0,desk);flat(DESK.width-.14,.055,DESK.depth-.08,'#d0ac72',0,DESK.top-.19,0,desk);for(const x of[-1.24,1.24]){soft(.76,.85,1.12,'#a98359',x,.49,0,desk);for(let i=0;i<3;i++){flat(.65,.018,.028,'#78563c',x,.29+i*.25,-.572,desk);soft(.28,.045,.045,'#dbbd7a',x,.39+i*.25,-.58,desk);}}
 flat(1.62,.60,.09,'#a47b53',0,.52,.47,desk);soft(1.40,.018,.59,'#607c70',0,DESK.top+.018,0,desk);soft(.50,.04,.38,'#f3e9ca',-.95,DESK.top+.03,-.16,desk);cylinder(.11,.10,.24,'#b7bca0',1.18,DESK.top+.12,.29,desk);for(const x of[1.13,1.22])flat(.025,.35,.025,'#a4714c',x,DESK.top+.32,.29,desk);
 const chair=group('principal-chair',STAFF.x,STAFF.z);soft(1.15,.09,.60,'#8b6849',0,.515,-.22,chair);soft(1.24,1.73,.14,'#947550',0,1.31,-.46,chair);soft(1.10,1.59,.07,'#b1a27f',0,1.30,-.40,chair);for(const x of[-.45,.45])for(const z of[-.45,.035])flat(.11,.48,.11,'#8b6849',x,.245,z,chair);for(const x of[-.85,.85]){soft(.16,.10,.63,'#b1a27f',x,.99,-.06,chair);for(const z of[-.29,.18])flat(.075,.40,.075,'#997a53',x,.75,z,chair);}chair.add(createPrincipalChairCushion());soft(.95,.08,.52,'#b89a70',0,.397,.39,chair);for(const x of[-.40,.40])flat(.075,.30,.075,'#8b6849',x,.20,.50,chair);
 const shelves=group('bookshelf',3.40,-6.08,0);flat(3.4,2.20,.10,'#9c7d52',0,1.18,-.16,shelves);for(const x of[-1.67,1.67])soft(.10,2.35,.44,'#b79662',x,1.21,0,shelves);for(const y of[.14,.70,1.26,1.82,2.36])flat(3.45,.09,.45,'#bd9d6e',0,y,0,shelves);for(let row=0;row<4;row++)for(let i=0;i<7;i++){const m=flat(.22,.37+(i%2)*.06,.26,['#77958b','#c0aa7b','#9ca9bb','#b18d79'][i%4],-1.32+i*.43,.38+row*.56,.025,shelves);if(i===6)m.rotation.z=-.07;}
 shelves.scale.x=.68;
 function plant(x,z){const g=group('plant',x,z);cylinder(.28,.21,.42,'#c8a077',0,.24,0,g);for(let i=0;i<5;i++){const a=i*1.256;sphere(.22,'#8ca986',Math.sin(a)*.15,.65+Math.cos(a)*.08,Math.cos(a)*.13,.7,1.4,.65,g);}}plant(-4.08,-5.4);
 const lamp=group('floor-lamp',4.20,4.95);cylinder(.24,.27,.10,'#8c7555',0,.06,0,lamp);cylinder(.035,.035,1.55,'#c3a463',0,.83,0,lamp);cylinder(.30,.49,.45,'#f2e4c0',0,1.72,0,lamp);
 function window(name,x,z,yaw,width){const g=group(name,x,z,yaw);soft(width+.2,1.88,.10,'#bda077',0,2.05,0,g);flat(width,1.69,.035,'#b8d4d5',0,2.05,.07,g);for(const xx of[-width/2,0,width/2])flat(.065,1.78,.075,'#f5ead0',xx,2.05,.11,g);flat(width,.07,.07,'#f5ead0',0,2.05,.11,g);soft(width+.4,.13,.29,'#c9aa7a',0,1.09,.13,g);for(const side of[-1,1])for(let i=0;i<4;i++)soft(.16,2.31,.16,i%2?'#c4cbae':'#aebc9d',side*(width/2+.10)+side*i*.115,1.93,.08,g);flat(width+1.15,.06,.09,'#bd9e67',0,3.12,.06,g);}
 window('rear-window',0,-6.25,0,2.7);window('rocking-window',-4.67,4.65,Math.PI/2,1.7);
 const rocker=group('rocking-chair',ROCK.x,ROCK.z,ROCK.yaw),rig=new THREE.Group();rig.name='principalOffice.rocking-rig';rig.position.y=ROCK.pivotY;rocker.add(rig);
 const rb=(w,h,d,c,x,y,z)=>soft(w,h,d,c,x,y-ROCK.pivotY,z,rig);rb(1.54,.12,1.13,'#b89c76',0,.48,-.25);rolled(1.12,.16,.85,'#e3d7b9',0,.62-ROCK.pivotY,0,0,.10,rig);rb(1.54,.85,.14,'#bead89',0,1.15,-.85);rb(1.40,.65,.09,'#e7dbbb',0,1.17,-.75);for(const x of[-.82,.82]){rb(.13,.11,1.55,'#b99b72',x,.96,-.19);for(const z of[-.36,.37])rb(.07,.59,.07,'#a58860',x,.49,z);const points=Array.from({length:25},(_,i)=>{const z=-.83+i/24*1.66;return new THREE.Vector3(x,.064+.23*z*z-ROCK.pivotY,z);});const mesh=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),24,.037,6,false),mat('#92764f'));mesh.name='principalOffice.rocking-runner';mesh.castShadow=mesh.receiveShadow=true;rig.add(mesh);}
 let disposed=false;return{root:office,fixtures,rocker,setRockingAngle(angle=0){if(!disposed)rig.rotation.x=THREE.MathUtils.clamp(Number.isFinite(angle)?angle:0,-.075,.075);},dispose(){disposed=true;},get rockingAngle(){return rig.rotation.x;}};
}
